const body = $input.first().json.body ?? {};
const msg = (body.message ?? '').toString().trim();
const cid = (body.conversation_id ?? '').toString().trim();
const profile = body.profile ?? null;
if (!msg) throw new Error('widget: message is required');
const userId = (cid && cid.startsWith('tmp')) ? cid : ('tmp-widget-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 8));
return [{ json: { chatInput: msg, userId, profile } }];

const d = $input.first().json.output;
const raw = typeof d === 'string' ? d : (d?.output ?? JSON.stringify(d));
function plainText(s) {
  return String(s ?? '')
    .replace(/<[^>]+>/g, '')
    .replace(/\[BLOCK[^\]]*\]/g, '')
    .replace(/\n{2,}/g, '\n')
    .trim();
}
function findBlock(html) {
  const i = html.indexOf('[BLOCK');
  if (i < 0) return null;
  const start = i + '[BLOCK'.length;
  const end = html.indexOf(']', start);
  const kind = end > 0 ? html.slice(start, end).trim() : '';
  return { kind, idx: i };
}
function stepObservation(toolName) {
  const steps = $input.first().json.intermediateSteps;
  if (!Array.isArray(steps)) return null;
  for (const st of steps) {
    const tool = st?.action?.tool;
    const obs = st?.observation;
    if (tool && String(tool).toLowerCase() === toolName && obs != null) return obs;
  }
  return null;
}
function firstJson(str) {
  const i = str.indexOf('{');
  const j = str.indexOf('[');
  const start = (i < 0 ? j : (j < 0 ? i : Math.min(i, j)));
  if (start < 0) return null;
  const s = str.slice(start);
  try { return JSON.parse(s); } catch { return null; }
}
function unwrap(v) {
  let cur = v;
  for (let d = 0; d < 6; d++) {
    if (typeof cur === 'string') {
      const parsed = firstJson(cur);
      if (parsed === null) return cur;
      cur = parsed;
      continue;
    }
    if (Array.isArray(cur)) {
      if (cur.length === 1 && cur[0] && typeof cur[0] === 'object' && cur[0].data !== undefined && typeof cur[0].data === 'string') {
        cur = cur[0].data;
        continue;
      }
      if (cur.length === 1 && cur[0] !== undefined) { cur = cur[0]; continue; }
      return cur;
    }
    if (cur && typeof cur === 'object') {
      if (cur.data !== undefined && typeof cur.data === 'string') { cur = cur.data; continue; }
      if (cur.data !== undefined && (Array.isArray(cur.data) || typeof cur.data === 'object')) { cur = cur.data; continue; }
      return cur;
    }
    return cur;
  }
  return cur;
}
function searchMsg() {
  const obs = stepObservation('search-products');
  if (!obs) return [];
  const text = typeof obs === 'string' ? obs : JSON.stringify(obs);
  const root = unwrap(text);
  const list = Array.isArray(root) ? root : (root && Array.isArray(root.data) ? root.data : null);
  if (!list) return [];
  return list.map(function (p) {
    if (!p) return null;
    const category = p.category || (p.category_info && p.category_info.name) || null;
    const brand = (p.brand_info && p.brand_info.name) || p.brand || null;
    return {
      id: p.id, name: p.name, slug: p.slug, price: p.nonformated_price,
      rating: p.rating || 0, reviewCount: p.total_reviews || 0,
      description: p.description || null, image: p.thumbnail_image || null,
      thumbnail: p.thumbnail_image || null, category, brand,
      hasVariants: !!p.variant_product,
      variants: (Array.isArray(p.choice_options) && p.choice_options.length > 0 ? p.choice_options[0].values || [] : []).map(function (v) {
        return { id: v.id || v.name, name: v.name, price: p.nonformated_price };
      }),
    };
  }).filter(Boolean);
}
function cartMsg() {
  const obs = stepObservation('get-cart');
  if (!obs) return [];
  const text = typeof obs === 'string' ? obs : JSON.stringify(obs);
  const root = unwrap(text);
  const shops = Array.isArray(root) ? root : (root && Array.isArray(root.cart_items) ? [root] : []);
  const items = [];
  for (const shop of shops) {
    for (const it of (shop.cart_items || [])) {
      items.push({
        key: String(it.id), product_id: it.product_id, variation_id: it.variation || null,
        name: it.product_name || 'Product', variant_name: it.variation || null,
        price: it.price, quantity: it.quantity,
      });
    }
  }
  return items;
}
const out = { reply: d, conversation_id: null, blocks: [], token_usage: null };
try { out.conversation_id = $('Prepare Input').first().json.userId; } catch {}
if (typeof d === 'string') {
  const b = findBlock(d);
  if (b) {
    const cleaned = d.replace(/\[BLOCK[^\]]*\]/g, '').replace(/\n[\n\s]*$/, '');
    out.reply = cleaned;
    const kind = b.kind.toLowerCase();
    if (kind === 'cart-table') {
      const items = cartMsg();
      const total = items.reduce(function (s2, i2) { return s2 + i2.price * i2.quantity; }, 0);
      out.blocks.push({ type: 'cart-table', items: items.slice(0, 20), total, count: items.length });
    } else if (kind === 'product-grid') {
      const list = searchMsg();
      if (list.length > 0) out.blocks.push({ type: 'product-grid', heading: 'Top picks', products: list.slice(0, 6), columns: 3 });
    }
  }
}
if (out.reply) out.reply = plainText(out.reply).slice(0, 8000);
let usage = null;
try { usage = $input.first().json.tokenUsage; } catch {}
if (usage) out.token_usage = { promptTokens: usage.promptTokens, completionTokens: usage.completionTokens, totalTokens: usage.totalTokens };
return [{ json: out }];
